# The pattern is clear:
# - Background color becomes 0
# - Foreground color becomes the original background color

# Transform function
def transform(grid):
    # Find the background color (most frequent) and foreground color (other)
    from collections import Counter
    all_cells = [cell for row in grid for cell in row]
    color_counts = Counter(all_cells)
    background_color = max(color_counts, key=color_counts.get)

    # Create output grid
    output = [[0 for _ in range(len(grid[0]))] for _ in range(len(grid))]
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == background_color:
                output[i][j] = 0  # background stays 0
            else:
                output[i][j] = background_color  # foreground becomes old background

    return output

# Test on demo input
result = transform(demo_input)
# Verify it matches demo output at the positions of interest
print("Demo transformation verified:", all(result[i][j] == demo_output[i][j] for i in range(28) for j in range(28)))

